1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, copyFileSync, existsSync } from 'node:fs';
4	import { tmpdir } from 'node:os';
5	import { join, dirname } from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	import { spawnSync } from 'node:child_process';
8	
9	// This test lives at <repo>/engine-tests/hooks/session-start-command.test.mjs.
10	const HOOKS_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'engine', 'hooks');
11	
12	// A hermetic corpus mirroring the real layout: the REAL engine/hooks/session-start-command.sh
13	// (it self-locates via BASH_SOURCE and resolves every step one level up at the
14	// corpus root) plus tiny STUB
15	// steps, so the test exercises the ORCHESTRATOR's own contract — sequence,
16	// stdout forwarding, lifecycle logging, exit 0 — without dragging in the real
17	// children and their dependencies.
18	function makeCorpus({ packStart = '', skills = '', env = '', interview = '', selftest = '', summary = '' } = {}) {
19	  const root = mkdtempSync(join(tmpdir(), 'claudinite-sessionstart-'));
20	  mkdirSync(join(root, 'engine', 'hooks'), { recursive: true });
21	  mkdirSync(join(root, 'engine', 'pack_loader'), { recursive: true });
22	  copyFileSync(join(HOOKS_DIR, 'session-start-command.sh'), join(root, 'engine', 'hooks', 'session-start-command.sh'));
23	  writeFileSync(join(root, 'engine', 'selftest.mjs'), selftest);
24	  writeFileSync(join(root, 'engine', 'pack_loader', 'run-pack-session-start.mjs'), packStart);
25	  writeFileSync(join(root, 'engine', 'pack_loader', 'mount-skills.mjs'), skills);
26	  writeFileSync(join(root, 'engine', 'pack_loader', 'env-requirements.mjs'), env);
27	  writeFileSync(join(root, 'engine', 'pack_loader', 'session-summary.mjs'), summary);
28	  // The interview machinery is the adoption skill's, bundled in the core pack.
29	  mkdirSync(join(root, 'packs', 'core', 'skills', 'adopt-claudinite'), { recursive: true });
30	  writeFileSync(join(root, 'packs', 'core', 'skills', 'adopt-claudinite', 'interview.mjs'), interview);
31	  return root;
32	}
33	
34	function run(corpus, projectDir, env = {}) {
35	  return spawnSync('bash', [join(corpus, 'engine', 'hooks', 'session-start-command.sh')], {
36	    encoding: 'utf8',
37	    env: { ...process.env, CLAUDE_PROJECT_DIR: projectDir, CLAUDINITE_HOOK_RUN: 'testrun', ...env },
38	  });
39	}
40	
41	test('orchestrator runs steps in order, forwards only step stdout, logs the lifecycle, exits 0', () => {
42	  const corpus = makeCorpus({
43	    packStart: 'process.stdout.write("PACKSTEP\\n");',
44	    summary: 'process.stdout.write("SUMMARY\\n");',
45	  });
46	  const projectDir = mkdtempSync(join(tmpdir(), 'claudinite-proj-'));
47	  const r = run(corpus, projectDir);
48	  assert.equal(r.status, 0);
49	  // Only the steps' stdout reaches the hook's stdout (→ session context), in
50	  // order, followed by the one-line confirmation footer; the timestamped log
51	  // goes to stderr + the file, never stdout.
52	  assert.ok(r.stdout.startsWith('PACKSTEP\nSUMMARY\n'), r.stdout);
53	  assert.match(r.stdout, /^Claudinite session-start: ran 6 steps \(mount-skills, selftest, pack-session-start, env-check, interview-check, session-summary\) at .+\.$/m);
54	  // No prose step, and none may come back (#807): static pack prose rides CLAUDE.md,
55	  // on a channel that does not truncate. This hook carries only what a session can
56	  // learn at session time.
57	  assert.doesNotMatch(r.stdout, /load-active-prose/);
58	  assert.doesNotMatch(r.stdout, /WARNING/); // all steps exited 0
59	  const log = readFileSync(join(projectDir, '.claudinite-hooks.log'), 'utf8');
60	  for (const s of [
61	    'run=testrun orchestrator: start',
62	    'selftest: start', 'selftest: done exit=0',
63	    'pack-session-start: start', 'pack-session-start: done exit=0',
64	    'mount-skills: start', 'env-check: start', 'interview-check: start',
65	    'session-summary: start', 'session-summary: done exit=0',
66	    'run=testrun orchestrator: done',
67	  ]) assert.ok(log.includes(s), `log missing line: ${s}\n--- log ---\n${log}`);
68	});
69	
70	test('the self-test judges a tree the converging steps have already converged', () => {
71	  // A probe must judge state that no LATER step in the same firing changes, and
72	  // mount-skills is the one step that converges what a probe reads: it rebuilds the
73	  // .claude/skills links probeSkillLinks judges. Ordered the other way round, a
74	  // resume whose mounts had gone stale reported dangling links that the same firing
75	  // repaired a second later — a finding about a state that no longer existed by the
76	  // time anyone read it, under a "re-run the skill mount" remedy that had already
77	  // run (#875).
78	  //
79	  // Asserted through the EFFECT rather than the label order, because the label
80	  // order is not the property: what matters is that the self-test can observe the
81	  // converged tree. The stub mount step converges (writes the marker) and the stub
82	  // self-test reports what it sees.
83	  const marker = (body) => `import { existsSync, writeFileSync } from "node:fs";\nconst m = process.env.CLAUDE_PROJECT_DIR + "/converged";\n${body}`;
84	  const corpus = makeCorpus({
85	    skills: marker('writeFileSync(m, "");'),
86	    selftest: marker('process.stdout.write((existsSync(m) ? "CONVERGED" : "STALE") + "\\n");'),
87	  });
88	  const projectDir = mkdtempSync(join(tmpdir(), 'claudinite-proj-'));
89	  const r = run(corpus, projectDir);
90	  assert.equal(r.status, 0);
91	  assert.match(r.stdout, /^CONVERGED$/m);
92	});
93	
94	test('a failing step never aborts the orchestrator nor turns the hook non-zero', () => {
95	  const corpus = makeCorpus({
96	    selftest: 'process.stdout.write("A\\n"); process.exit(1);', // a step exits non-zero...
97	    packStart: 'process.stdout.write("B\\n");',                // ...the rest still runs
98	  });
99	  const projectDir = mkdtempSync(join(tmpdir(), 'claudinite-proj-'));
100	  const r = run(corpus, projectDir);
101	  assert.equal(r.status, 0);            // a non-zero SessionStart exit would discard the context
102	  assert.ok(r.stdout.startsWith('A\nB\n'), r.stdout); // later steps still ran and forwarded
103	  // The footer flags the crashed step so a semantic failure is visible in-context.
104	  assert.match(r.stdout, /WARNING: selftest exited 1/);
105	  const log = readFileSync(join(projectDir, '.claudinite-hooks.log'), 'utf8');
106	  assert.ok(log.includes('selftest: done exit=1'), log);
107	});
